func fuzz() {
extension String {

    var escapesAdded: String {
        self.unicodeScalars
            .reduce("")
{ $0 + $1.escaped(asASCII: false)}
    }

    var escapesRemoved: String {
        var modified = self
        for entity in [
"\0", "\t", "\n", "\r", "\"", "\\"] {
            let escapedCharacter = entity.escapesAdded
            modified = modified.replacingOccurrences(of: escapedCharacter, with: entity)
        }
        return modified
    }
}
public protocol ExpressionMacro: FreestandingMacro {
  /// Expand a macro described by the given freestanding macro expansion
  /// within the given context to produce a replacement expression.
  static func expansion(
    of node: some FreestandingMacroExpansionSyntax,
    in context: some MacroExpansionContext
  ) throws -> ExprSyntax
}
}

